<?php
namespace App\Http\Controllers;
use App\Http\Requests\StorePembinaanRequest;
use App\Models\Instansi;
use App\Models\Pembinaan;
use App\Models\Pegawai;
use App\Models\KategoriInstansi;
class PembinaanController extends Controller {
  public function index() { $this->authorize('viewAny', Pembinaan::class); $query=Pembinaan::with(['instansi','pegawai','creator']); $query->latest('tanggal_mulai'); if(request('q')){$q=request('q');$query->where(fn($w)=>$w->where('layanan','like',"%$q%")->orWhere('lokasi','like',"%$q%"));} if(request('instansi_id'))$query->where('instansi_id',request('instansi_id')); if(request('status_dokumen'))$query->where('status_dokumen',request('status_dokumen')); if(request('tanggal_mulai'))$query->whereDate('tanggal_mulai','>=',request('tanggal_mulai')); if(request('tanggal_selesai'))$query->whereDate('tanggal_mulai','<=',request('tanggal_selesai')); $items=$query->paginate(15)->withQueryString(); return view('pembinaan.index',['items'=>$items,'instansi'=>Instansi::with('kategoriInstansi')->where('status_aktif',true)->orderBy('nama')->get()]); }
 public function create() { $this->authorize('create',Pembinaan::class); return view('pembinaan.form',['item'=>null,'instansi'=>Instansi::with('kategoriInstansi')->where('status_aktif',true)->orderBy('nama')->get(),'pegawai'=>Pegawai::where('status_aktif',true)->orderBy('nama_lengkap')->get(),'kategori'=>KategoriInstansi::where('status_aktif',true)->orderBy('nama')->get()]); }
  public function store(StorePembinaanRequest $request) { $data=$request->safe()->except(['pegawai','peran','created_by','workflow_status']); $data['created_by']=$request->user()->id; $data['workflow_status']=$request->input('workflow_status','draft') === 'submitted' ? 'submitted' : 'draft'; $item=Pembinaan::create($data); $this->syncPegawai($request,$item); $this->storeUploadedFiles($request,$item); return redirect()->route('pembinaan.show',$item)->with('success',$data['workflow_status']==='submitted'?'Pembinaan berhasil disubmit.':'Pembinaan berhasil disimpan sebagai draft.'); }
 public function show(Pembinaan $pembinaan) { $this->authorize('view',$pembinaan); return view('pembinaan.show',['item'=>$pembinaan->load(['instansi','pegawai','creator','files.uploader'])]); }
 public function edit(Pembinaan $pembinaan) { $this->authorize('update',$pembinaan); return view('pembinaan.form',['item'=>$pembinaan->load(['pegawai','files']),'instansi'=>Instansi::with('kategoriInstansi')->where('status_aktif',true)->orderBy('nama')->get(),'pegawai'=>Pegawai::where('status_aktif',true)->orderBy('nama_lengkap')->get(),'kategori'=>KategoriInstansi::where('status_aktif',true)->orderBy('nama')->get()]); }
  public function update(StorePembinaanRequest $request,Pembinaan $pembinaan) { $data=$request->safe()->except(['pegawai','peran','created_by','workflow_status']); $data['workflow_status']=$request->input('workflow_status','draft') === 'submitted' ? 'submitted' : 'draft'; $pembinaan->update($data); $this->syncPegawai($request,$pembinaan); $this->storeUploadedFiles($request,$pembinaan); return redirect()->route('pembinaan.show',$pembinaan)->with('success',$data['workflow_status']==='submitted'?'Pembinaan berhasil disubmit.':'Pembinaan berhasil disimpan sebagai draft.'); }
 private function syncPegawai(StorePembinaanRequest $request, Pembinaan $item): void { $pegawai = $request->input('pegawai', []); $peran = $request->input('peran', []); $sync = []; foreach ($pegawai as $pegawaiId) { $sync[$pegawaiId] = ['peran' => $peran[$pegawaiId] ?? 'Tim']; } $item->pegawai()->sync($sync); }
 private function storeUploadedFiles(StorePembinaanRequest $request, Pembinaan $item): void { foreach ([['laporan_file','laporan','Publikasi'],['materi_file','materi',$request->input('materi_visibilitas','Private')]] as [$key,$jenis,$visibilitas]) if ($request->hasFile($key)) { $file=$request->file($key); $item->files()->create(['uploaded_by'=>$request->user()->id,'jenis'=>$jenis,'nama_asli'=>$file->getClientOriginalName(),'path'=>$file->store('pembinaan/'.$item->id,'local'),'mime_type'=>$file->getMimeType(),'ukuran'=>$file->getSize(),'visibilitas'=>$visibilitas]); } }
 public function destroy(Pembinaan $pembinaan) { $this->authorize('delete',$pembinaan); $pembinaan->delete(); return redirect()->route('pembinaan.index')->with('success','Pembinaan berhasil dihapus.'); }
}
